export type Cell = [number, number]; // [x, y]

export function nextGeneration(cells: Cell[]): Cell[] {
  return cells.filter(([x, y]) => {
    let neighbors = 0;
    for (const [ox, oy] of cells) {
      if (Math.abs(ox - x) <= 1 && Math.abs(oy - y) <= 1 && !(ox === x && oy === y)) {
        neighbors++;
      }
    }
    return neighbors >= 2;
  });
}
EOF
